sys_ui_action.client_script_v2:
function onClick(g_form) {
	console.debug("UI Action:Request: onClick()");
	// debugger;
	g_modal.confirm("ボタン押してね")
	.then(ret => {
		// はい 選択時
		// alert("ボタン押したよ");
		console.debug("ret=", ret); // true
		g_form.submit("act_request");
	})
	.catch(err => {
		// alert("テスト2");
		// いいえ、クローズアイコン選択時
		console.error(err);
		});
}

sys_ui_action.script:
// ↓Conditionに入れる
// current.canWrite() && current.state == Const.STATE.OPEN  && current.stage == Const.STAGE.WAIT_REQUEST

function actRequest(is_destructive) {
	// 入力されていない必須項目がある場合はreturn
	alert('テスト');
	if (!g_form.mandatoryCheck()) return;
	g_user.bnc.confirm(getMessage("Confirmation"), getMessage("Are you sure to request?"), {
		titleOk: "Request",
		titleCancel: "No",
		funcOk: function () {
			gsftSubmit(null, g_form.getFormElement(), "act_request");
		},
	});
}
// gs.addErrorMessage('テスト3');
/**
 * サーバー処理
 */
if (typeof window == "undefined") {
	// var log = new global.GSLog(gs.getCurrentScopeName() + ".LogLevel", "Request");
	// (() => {
	// 	let info = getUserInfo();
	// 	if (!info) {
	// 		gs.addErrorMessage(gs.getMessage("Failed to request because your have no affiliation.") + "<br>" + "Please set your Affiliation from User Profile Menu.");
	// 		current.setAbortAction(true);
	// 		action.setRedirectURL(current);
	// 		return;
	// 	}

		current.state = Const.STATE.WIP;
		current.is_remand = false;
		current.is_regain = false;

		current.details = action.getURLParameter("test");
		current.dept_code = action.getURLParameter("dept_code");

		// var comms = new ApprovalUtils()._buildComments(current, current.user_input.toString(), "requested");
		var comms = "test";
		current.comments = comms;
		// current.comments = `起票者：${current.opened_by.u_name_ja}
		// 所属：${info.dept_fullname}
		// コメント：${current.user_input}`;

		current.update();

		runSubFlow();
		action.setRedirectURL(current);
		// gs.addInfoMessage(gs.getMessage("Requested") + "：" + current.getLabel() + "：" + current.number);
		gs.addInfoMessage(gs.getMessage("Requested approval for {0}", current.number));
		// gs.eventQueue(gs.getCurrentScopeName() + ".approval_request", current, current.stage);

// 	})();
