function runSubFlow() {
	log.debug("runSubFlow(): start");
	try {
		var inputs = {};
		inputs['record'] = current; // GlideRecord of table: x_khi_z1_orggmgr_bulk_personnel 

		// Start Asynchronously: Uncomment to run in background. Code snippet will not have access to outputs.
		// sn_fd.FlowAPI.getRunner().subflow('x_khi_z1_orggmgr.sub_single_approval').inBackground().withInputs(inputs).run();

		// Execute Synchronously: Run in foreground. Code snippet has access to outputs.
		var result = sn_fd.FlowAPI.getRunner().subflow('x_1813832_1_persona_change_req.main_approval_request_for_base_table').inForeground().withInputs(inputs).run();
		var outputs = result.getOutputs();

		// Get Outputs:
		// Note: outputs can only be retrieved when executing synchronously.
		var status = outputs['status']; // Choice
		log.debug("status=" + status);

	} catch (ex) {
		var message = ex.getMessage();
		gs.error(message);
		log.error(message);
	}
}

// ここで呼び出しているかも
function getUserInfo() {
	let info = new UserUtils().getUserInfo();
	if (info && info.affiliation_code)
		return info;

	global.JSUtil.logObject(info);
	return;
}
function setOpenedByInfo(rec, info) {

}

function debug(msg) {
	if (gs.getProperty(gs.getCurrentScopeName() + '.LogLevel') != "debug") return;
	gs.addInfoMessage("[Debug] " + gs.getMessage(msg));
}
